    private AvifVectors() {
    }

    static Path fetch(String path) {
        var sha = SHA256.get(path);
        if (sha == null) {
            throw new IllegalArgumentException("unpinned AVIF vector " + path);
        }
        return Conformance.fetch("avif-" + path.replace('/', '-'), BASE + path, sha);
    }

    static byte[] read(String path) {
        try {
            return Files.readAllBytes(fetch(path));
        } catch (IOException exception) {
            throw new UncheckedIOException(exception);
        }
    }
